<?php
namespace App\Modules\Orders\Application;
use App\Modules\Inventory\Domain\Models\InventoryBalance;use App\Modules\Orders\Domain\Enums\ProductionDemandStatus;use App\Modules\Orders\Domain\Enums\ReservationStatus;use App\Modules\Orders\Domain\Enums\SalesOrderStatus;use App\Modules\Orders\Domain\Models\ProductionDemand;use App\Modules\Production\Domain\Models\ProductionOrder;use Illuminate\Support\Facades\DB;
class FulfillProductionDemand {public function execute(ProductionOrder $production):void{$production->loadMissing(['outputs','orderAllocations.salesOrderLine.order','orderAllocations.salesOrderLine.presentation']);$remaining=$production->outputs->groupBy('recipe_compatible_product_id')->map(fn($g)=>(string)$g->sum(fn($o)=>(float)$o->quantity))->all();foreach($production->orderAllocations as $allocation){$line=$allocation->salesOrderLine;$demand=ProductionDemand::query()->where('sales_order_line_id',$line->id)->sole();$available=$remaining[$demand->recipe_compatible_product_id]??'0';$quantity=(string)min((float)$allocation->planned_quantity,(float)$available);if(bccomp($quantity,'0',6)>0){$balance=InventoryBalance::query()->where('presentation_id',$line->presentation_id)->lockForUpdate()->sole();$balance->update(['reserved_quantity'=>bcadd($balance->reserved_quantity,$quantity,6)]);$line->reservations()->create(['presentation_id'=>$line->presentation_id,'production_order_allocation_id'=>$allocation->id,'quantity'=>$quantity,'status'=>ReservationStatus::Active,'reserved_at'=>now()]);$line->update(['produced_quantity'=>bcadd($line->produced_quantity,$quantity,6),'reserved_quantity'=>bcadd($line->reserved_quantity,$quantity,6)]);$allocation->update(['produced_quantity'=>$quantity,'reserved_quantity'=>$quantity]);$remaining[$demand->recipe_compatible_product_id]=bcsub($available,$quantity,6);}$pending=max(0,(float)$line->ordered_quantity-(float)$line->fresh()->reserved_quantity);$demand->update(['pending_quantity'=>$pending,'status'=>$pending<=0?ProductionDemandStatus::Fulfilled:ProductionDemandStatus::Pending]);}
foreach($production->orderAllocations->pluck('salesOrderLine.order')->unique('id') as $order){$order->load('lines');$ready=$order->lines->every(fn($line)=>bccomp($line->reserved_quantity,bcsub($line->ordered_quantity,$line->delivered_quantity,6),6)>=0);$from=$order->status;$to=$ready?SalesOrderStatus::Ready:SalesOrderStatus::PendingProduction;if($from!==$to){$order->update(['status'=>$to]);$order->histories()->create(['from_status'=>$from->value,'to_status'=>$to->value,'changed_by'=>$production->created_by,'changed_at'=>now(),'notes'=>"Resultado de {$production->document_number}."]);}}}}
